import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/%E3%80%90%E6%9B%B8%E7%B1%8D%E3%80%91%E3%82%AE%E3%83%A3%E3%83%8E%E3%83%B3%E3%82%B0%E7%94%9F%E7%90%86%E5%AD%A6.html","title":"【書籍】ギャノング生理学","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":1.31,"words":394},"filePathRelative":"【書籍】ギャノング生理学.md"}`),a={name:`【書籍】ギャノング生理学.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="【書籍】ギャノング生理学" tabindex="-1"><a class="header-anchor" href="#【書籍】ギャノング生理学"><span>【書籍】ギャノング生理学</span></a></h1><p><a href="./生理学.html">生理学</a>, <a href="./生物学.html">生物学</a></p><ul><li><a href="https://amzn.to/46xgurz" target="_blank" rel="noopener noreferrer">amazon: ギャノング生理学 原書26版</a></li><li><a href="https://hb.afl.rakuten.co.jp/ichiba/517bc8c0.0747eabc.517bc8c1.b6411453/?pc=https%3A%2F%2Fitem.rakuten.co.jp%2Frakutenkobo-ebooks%2Fdca9c6a420a5321f92e81c1e0a2825b1%2F&amp;link_type=text&amp;ut=eyJwYWdlIjoiaXRlbSIsInR5cGUiOiJ0ZXh0Iiwic2l6ZSI6IjI0MHgyNDAiLCJuYW0iOjEsIm5hbXAiOiJyaWdodCIsImNvbSI6MSwiY29tcCI6ImRvd24iLCJwcmljZSI6MSwiYm9yIjoxLCJjb2wiOjEsImJidG4iOjEsInByb2QiOjAsImFtcCI6ZmFsc2V9" target="_blank" rel="noopener noreferrer">kobo: ギャノング生理学 原書26版 （電子書籍版）</a></li></ul><h2 id="購入-2026-03-02-月" tabindex="-1"><a class="header-anchor" href="#購入-2026-03-02-月"><span>購入 2026-03-02 (月)</span></a></h2><p>電子化されている生理学の教科書が何か欲しいなぁ、と探していた所、この本を見つけた。 <a href="./【書籍】新しい人体の教科書.html">【書籍】新しい人体の教科書</a>で心臓のあたりを読んでいてもうすぐ読み終わりそうで、もうちょっと深い話を読みたいな、と思ったので購入。 ちょっとレイアウトが電子に優しくない感じではあるが、<a href="./LenovoTabP12.html">LenovoTabP12</a>が火を吹くぜ！って感じの本でもある。</p><h2 id="_29章、心臓の電気的活動のあたりを読む、素晴らしい本-2026-03-03-火" tabindex="-1"><a class="header-anchor" href="#_29章、心臓の電気的活動のあたりを読む、素晴らしい本-2026-03-03-火"><span>29章、心臓の電気的活動のあたりを読む、素晴らしい本 2026-03-03 (火)</span></a></h2><p>飛行機で29章を読んでみた。素晴らしい。買ってよかった。</p><p>十分に詳しく、知りたい事が全部書いてあり、それでいて全部読めるくらいの簡潔さ。 図も豊富でわかりやすい。</p><p>29章から読んだけれど、その前の章の内容が無くてもかなり理解出来る。5章には組織の説明がいろいろあるっぽくてそのあたりの知識は前提にされているので分からない部分もあるけれど、 そういう場所は小さい範囲に収まっているし、ちゃんと参照があるので必要になったら読めばいいか、という感じで進められる。</p><p>また、実際よくある病気の病名との関連や心電図などの診察との関わりが多く書いてあるので、 医療の内容を理解したいという自分のような人間にちょうど良い。 腕と胸の電極で一体何を測っているのか、それは生理学的な反応とどう関係があるのか、といったような話は、健康診断などを受ける側としてもなかなか興味深い。</p><p>一方で、生理学を勉強した事が無い人にはちょっと難しい本だな、とも思う。 かなり本格的な学術書なので、何も知らない人がこの本の29章から読もうと思うと全然分からないだろうな、という気がする。 どこかで一度ちゃんと勉強した事ある人が、思い出したりより詳しく特定の場所を知りたくて読むのにはとても良いと思う。</p><h3 id="生理学の入門をちゃんと学んだご利益を感じる本" tabindex="-1"><a class="header-anchor" href="#生理学の入門をちゃんと学んだご利益を感じる本"><span>生理学の入門をちゃんと学んだご利益を感じる本</span></a></h3><p>何か興味のある分野について、この本の該当章をちゃんと理解出来る、というのは、<a href="./生理学.html">生理学</a>や細胞生物学などの<a href="./生物学.html">生物学</a>をちゃんと勉強したご利益に思う。</p><p>現代の高度かつ複雑な医療を、まったく次元の異なる解像度で理解出来るようになる。 それは人間の体で生きていく我々皆にとって価値のある事だし、 また親や身の回りの家族などが医療のお世話になる時にもとても役に立つ。</p><p>たぶん日常生活を送る上でこれほど役に立つ学問は無いんじゃないか。</p><p>この本の該当章を読めるようになる、というのが生理学をどこかでちゃんと勉強する意義で、そうなっておくのは成人の教養として重要なものだと思う。 29章を一通り読んで、そんな事を思った。</p>`,16)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};